function exceeds(rate, threshold) {
  return rate > threshold;
}

function canaryUsers(total, percent) {
  return Math.floor((total * percent) / 100);
}

function bucketIsNew(bucket, percent) {
  return bucket < percent;
}

function nextStage(current, stages) {
  const i = stages.indexOf(current);
  return i >= 0 && i < stages.length - 1 ? stages[i + 1] : null;
}

function usersOnOld(total, percent) {
  return total - Math.floor((total * percent) / 100);
}

function enoughTraffic(total, minRequests) {
  return total >= minRequests;
}

function stageLabel(percent) {
  if (percent === 0) return "off";
  if (percent === 100) return "full";
  return "canary";
}

function shouldHalt(errors, total, thresholdPercent) {
  if (total === 0) return false;
  return errors * 100 > thresholdPercent * total;
}

function shouldHaltBySegment(segments, thresholdPercent) {
  return segments.some(
    (s) => s.total > 0 && s.errors * 100 > thresholdPercent * s.total,
  );
}

