function canaryAction(errors, total, thresholdPercent, minRequests) {
  if (total < minRequests) return "wait";
  if (errors * 100 > thresholdPercent * total) return "halt";
  return "advance";
}

function nextPercent(current, stages, healthy) {
  if (!healthy) return 0;
  const i = stages.indexOf(current);
  return i >= 0 && i < stages.length - 1 ? stages[i + 1] : current;
}
